<script setup lang="ts">
import { computed, ref } from 'vue'
import { Save, Code2, Copy, Plus, X } from 'lucide-vue-next'
import type { FlowFile } from '@zedflow/sdk'
import { typeLabel } from '../../contextEngine'

import { exportedFlows, flowExports, routeModes, type BridgeStudioController } from '../../compositionEngine'
import type { Endpoint, FlowDefinition } from '@zedflow/sdk'
import PredicateEditor from '../PredicateEditor.vue'
import AppDialog from '../AppDialog.vue'
const props=defineProps<{studio:BridgeStudioController;flows:FlowFile[];active:boolean}>()
const draft=computed(()=>props.studio.current),bridge=computed(()=>draft.value.bridge),files=computed(()=>exportedFlows(props.flows))
const sourceOpen=ref(false),reloadOpen=ref(false),aliasName=ref(''),connectionName=ref(''),bindingName=ref('')
const tab=ref<'connections'|'bindings'>('connections')
const invalid=computed(()=>!!draft.value.file&&!draft.value.file.bridge)
const instances=computed(()=>['root',...Object.keys(bridge.value.imports)])
function definition(instance:string):FlowDefinition|undefined{const key=instance==='root'?draft.value.rootFlow:bridge.value.imports[instance]?.flow;return flowExports(props.flows.find(file=>file.key===key)?.composition)?.contract}
function ports(instance:string,family:'entries'|'branches'|'data'|'requires'){return Object.keys(definition(instance)?.[family]||{})}
function endpoint(value:Endpoint,instance:string){value.instance=instance;value.port=''}
function add(kind:'import'|'connection'|'binding'){
  const input=kind==='import'?aliasName:kind==='connection'?connectionName:bindingName,id=input.value.trim(),target=kind==='import'?bridge.value.imports:kind==='connection'?bridge.value.connections:bridge.value.bindings
  if(!id||id==='root'||id.includes('/')||Object.hasOwn(target,id)){draft.value.error='Choisissez une identité unique, sans slash et différente de root.';return}
  if(kind==='import')bridge.value.imports[id]={flow:files.value[0]?.key||''}
  if(kind==='connection')bridge.value.connections[id]={from:{instance:'root',port:''},to:{instance:Object.keys(bridge.value.imports)[0]||'root',port:''},mode:'callAwait',invocation:'node'}
  if(kind==='binding')bridge.value.bindings[id]={from:{instance:'root',port:''},to:{instance:Object.keys(bridge.value.imports)[0]||'root',port:''},permissions:{read:true,write:false}}
  input.value='';draft.value.error=''
}
function key(event:KeyboardEvent){if(props.active&&(event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='s'){event.preventDefault();void props.studio.save()}}
</script>
<template><section class="context-studio bridge-studio" aria-label="Studio de bridges" @keydown="key"><header class="ctx-toolbar"><div class="ctx-strategy-title"><input v-model="draft.key" aria-label="Identifiant du bridge" :readonly="!!draft.file||draft.pending"/><small>{{JSON.stringify(bridge)===draft.saved?'Version enregistrée':'Brouillon non enregistré'}}<template v-if="draft.file"> · {{draft.file.hash.slice(0,10)}}</template></small></div><div class="ctx-toolbar-actions"><button :disabled="!draft.file?.source" aria-label="Afficher le Rust du bridge" @click="sourceOpen=true"><Code2 :size="14"/></button><button :disabled="draft.pending||invalid" aria-label="Dupliquer le bridge" @click="studio.create(true)"><Copy :size="14"/></button><button v-if="draft.file" :disabled="draft.pending" @click="reloadOpen=true">Recharger</button><button :disabled="draft.pending||invalid||!studio.workspaceId" @click="studio.save()"><Save :size="14"/>Enregistrer le bridge</button></div></header><p v-if="draft.error" role="alert" class="ctx-alert ctx-error">{{draft.error}}</p><p v-if="draft.notice" role="status" class="ctx-alert">{{draft.notice}}</p><div class="bridge-layout"><aside class="bridge-imports"><h2>Instances et dépendances</h2><label>Flow racine pour lire les ports<select v-model="draft.rootFlow" aria-label="Flow racine pour les ports"><option value="" disabled>Choisir un flow exposé</option><option v-for="file in files" :key="file.key" :value="file.key">{{file.name}}</option></select></label><p class="ctx-hint">root désigne le flow d’entrée au lancement. Ce choix sert ici à explorer ses ports.</p><fieldset :disabled="draft.pending||invalid"><div v-for="(item,alias) in bridge.imports" :key="alias" class="bridge-import"><header><strong>{{alias}}</strong><button :aria-label="`Retirer l’import ${alias}`" @click="delete bridge.imports[alias]"><X :size="12"/></button></header><label>Définition de {{alias}}<select :aria-label="`Définition de ${alias}`" v-model="item.flow"><option value="" disabled>Choisir un flow exposé</option><option v-for="file in files" :key="file.key" :value="file.key">{{file.name}}</option></select></label><label>Réutiliser une instance · facultatif<input :value="item.reuse" @input="($event.target as HTMLInputElement).value?item.reuse=($event.target as HTMLInputElement).value:delete item.reuse" placeholder="root ou bridge/alias"/></label><small>Sans réutilisation, cet import crée une instance indépendante.</small></div><div class="ctx-add-field"><input v-model="aliasName" aria-label="Alias du flow importé" placeholder="Alias local" @keydown.enter.prevent="add('import')"/><button aria-label="Ajouter un import" @click="add('import')"><Plus :size="13"/></button></div><h3>Bridges requis</h3><label v-for="file in studio.session.files.filter(file=>file.key!==draft.key&&file.bridge)" :key="file.key" class="ctx-checkbox"><input v-model="bridge.requires" type="checkbox" :value="file.key"/>{{file.key}}</label><p v-if="!studio.session.files.some(file=>file.key!==draft.key&&file.bridge)" class="ctx-hint">Aucune autre définition disponible.</p></fieldset></aside><main class="bridge-connections"><nav class="ctx-editor-tabs" aria-label="Branchements du bridge"><button :aria-pressed="tab==='connections'" @click="tab='connections'">Routes</button><button :aria-pressed="tab==='bindings'" @click="tab='bindings'">Données partagées</button></nav><p class="ctx-hint">Activer un bridge rend ses routes présentes dans le graphe résolu. Une garde détermine ensuite leur éligibilité à chaque passage.</p><fieldset :disabled="draft.pending||invalid"><template v-if="tab==='connections'"><article v-for="(connection,id) in bridge.connections" :key="id" class="bridge-connection" :data-connection-id="id"><header><h3>{{id}}</h3><button :aria-label="`Retirer la connexion ${id}`" @click="delete bridge.connections[id]"><X :size="13"/></button></header><div class="bridge-endpoints"><fieldset><legend>Depuis un branchement</legend><label>Instance source<select :aria-label="`Instance source ${id}`" :value="connection.from.instance" @change="endpoint(connection.from,($event.target as HTMLSelectElement).value)"><option v-for="name in instances" :key="name">{{name}}</option></select></label><label>Port source<select :aria-label="`Port source ${id}`" v-model="connection.from.port"><option value="" disabled>Choisir un branchement</option><option v-for="name in ports(connection.from.instance,'branches')" :key="name">{{name}}</option></select></label></fieldset><span aria-hidden="true">→</span><fieldset><legend>Vers une entrée</legend><label>Instance cible<select :aria-label="`Instance cible ${id}`" :value="connection.to.instance" @change="endpoint(connection.to,($event.target as HTMLSelectElement).value)"><option v-for="name in instances" :key="name">{{name}}</option></select></label><label>Entrée cible<select :aria-label="`Entrée cible ${id}`" v-model="connection.to.port"><option value="" disabled>Choisir une entrée</option><option v-for="name in ports(connection.to.instance,'entries')" :key="name">{{name}}</option></select></label></fieldset></div><div class="ctx-row"><label>Mode<select :aria-label="`Mode de ${id}`" v-model="connection.mode"><option v-for="mode in routeModes" :key="mode.value" :value="mode.value">{{mode.label}}</option></select></label><label>Invocation<select :aria-label="`Invocation de ${id}`" v-model="connection.invocation"><option v-for="kind in definition(connection.from.instance)?.branches[connection.from.port]?.invocations||['node','condition','tool']" :key="kind" :value="kind">{{{node:'Nœud',condition:'Condition',tool:'Appel d’outil',context:'Production de contexte'}[kind]}}</option></select></label></div><small>{{routeModes.find(mode=>mode.value===connection.mode)?.detail}}</small><label v-if="connection.invocation==='tool'">Nom de l’outil exposé<input v-model="connection.toolName" placeholder="review_document"/></label><label class="ctx-checkbox"><input type="checkbox" :checked="!!connection.condition" @change="connection.condition=($event.target as HTMLInputElement).checked?{kind:'compare',field:'input',operator:'exists'}:null"/>Condition d’éligibilité</label><PredicateEditor v-if="connection.condition" v-model="connection.condition"/></article><div class="ctx-add-field"><input v-model="connectionName" aria-label="Nom de la connexion" placeholder="Nouvelle connexion" @keydown.enter.prevent="add('connection')"/><button @click="add('connection')"><Plus :size="13"/>Ajouter une connexion</button></div></template><template v-else><article v-for="(binding,id) in bridge.bindings" :key="id" class="bridge-connection"><header><h3>{{id}}</h3><button :aria-label="`Retirer la liaison ${id}`" @click="delete bridge.bindings[id]"><X :size="13"/></button></header><div class="bridge-endpoints"><fieldset><legend>Donnée exposée</legend><select :aria-label="`Instance de la donnée ${id}`" :value="binding.from.instance" @change="endpoint(binding.from,($event.target as HTMLSelectElement).value)"><option v-for="name in instances" :key="name">{{name}}</option></select><select :aria-label="`Donnée source ${id}`" v-model="binding.from.port"><option value="" disabled>Choisir une donnée</option><option v-for="name in ports(binding.from.instance,'data')" :key="name">{{name}}</option></select></fieldset><span aria-hidden="true">→</span><fieldset><legend>Donnée requise</legend><select :aria-label="`Instance requérante ${id}`" :value="binding.to.instance" @change="endpoint(binding.to,($event.target as HTMLSelectElement).value)"><option v-for="name in instances" :key="name">{{name}}</option></select><select :aria-label="`Donnée requise ${id}`" v-model="binding.to.port"><option value="" disabled>Choisir une exigence</option><option v-for="name in ports(binding.to.instance,'requires')" :key="name">{{name}}</option></select></fieldset></div><label>Permissions transmises<select :value="binding.permissions.write?'write':'read'" aria-label="Permissions transmises" @change="binding.permissions={read:true,write:($event.target as HTMLSelectElement).value==='write'}"><option value="read">Lecture</option><option value="write">Lecture et écriture</option></select></label><small v-if="definition(binding.from.instance)?.data[binding.from.port]">{{typeLabel(definition(binding.from.instance)!.data[binding.from.port].dataType)}} · La résolution contrôle le sens des types et les permissions.</small></article><div class="ctx-add-field"><input v-model="bindingName" aria-label="Nom de la liaison de données" placeholder="Nouvelle liaison" @keydown.enter.prevent="add('binding')"/><button @click="add('binding')"><Plus :size="13"/>Ajouter une liaison</button></div></template></fieldset></main></div><AppDialog v-model:open="sourceOpen" title="Rust du bridge" wide><p v-if="JSON.stringify(bridge)!==draft.saved" class="ctx-hint">Source de la dernière version enregistrée.</p><pre class="source-preview">{{draft.file?.source}}</pre></AppDialog><AppDialog v-model:open="reloadOpen" title="Recharger le bridge"><p>Remplacer ce brouillon par le fichier Rust présent sur le disque ?</p><footer><button @click="reloadOpen=false">Conserver le brouillon</button><button @click="studio.open(draft.file!,true);reloadOpen=false">Recharger depuis le disque</button></footer></AppDialog></section></template>
<style scoped>.bridge-layout{display:grid;grid-template-columns:280px minmax(360px,1fr);flex:1;min-height:0}.bridge-imports{padding:20px;border-right:1px solid #37373e;overflow:auto;display:flex;flex-direction:column;gap:12px}.bridge-import{display:flex;flex-direction:column;gap:9px;border-top:1px solid #42424b;padding:15px 0}.bridge-import>header,.bridge-connection>header{display:flex;justify-content:space-between;align-items:center}.bridge-import>header button,.bridge-connection>header button{background:transparent;border:0;padding:3px}.bridge-connections{padding:20px;overflow:auto;min-width:0}.bridge-connection{padding:18px;border:1px solid #45454e;border-radius:6px;margin:16px 0;display:flex;flex-direction:column;gap:12px;background:#222227}.bridge-endpoints{display:grid;grid-template-columns:1fr 25px 1fr;align-items:center;gap:8px}.bridge-endpoints>fieldset{display:flex;flex-direction:column;gap:8px;min-width:0}.bridge-endpoints legend{font-size:11px;color:#93939e;margin:0 0 8px}.bridge-endpoints>span{text-align:center;color:#9999a8}.bridge-imports h3{margin-top:16px}.bridge-connections .ctx-add-field button{display:flex;align-items:center;gap:7px;white-space:nowrap}@media(max-width:950px){.bridge-layout{display:flex;flex-direction:column;overflow:auto}.bridge-imports,.bridge-connections{overflow:visible}.bridge-imports{border-right:0;border-bottom:1px solid #393940}.bridge-endpoints{grid-template-columns:1fr}.bridge-endpoints>span{transform:rotate(90deg)}}
</style>
